import type { PlacementDrive } from './placement-drive-model';

export interface EligibilityCriteria {
  /**
   * @displayName Eligibility Criteria ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Criteria Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  criteriaName: string;
  /**
   * @displayName Allowed Departments
   * @validationRule Required for create/update operations
   */
  allowedDepartments: string;
  /**
   * @displayName Allowed Years
   * @validationRule Required for create/update operations
   */
  allowedYears: string;
  /**
   * @displayName Maximum Backlogs
   * @validationRule Required for create/update operations
   */
  maximumBacklogs: number;
  /**
   * @displayName Minimum CGPA
   * @validationRule Required for create/update operations
   */
  minimumCGPA: number;
  /**
   * @displayName Placement Drive
   * @validationRule Required for create/update operations
   */
  placementDrive: Pick<PlacementDrive, 'id' | 'companyName'>;
}

export const _EligibilityCriteria = 'EligibilityCriteria' as const;
